func testEmpresasUpdate(t *testing.T) {
	t.Parallel()

	if 0 == len(empresaPrimaryKeyColumns) {
		t.Skip("Skipping table with no primary key columns")
	}
	if len(empresaAllColumns) == len(empresaPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &Empresa{}
	if err = randomize.Struct(seed, o, empresaDBTypes, true, empresaColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Empresa struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := Empresas().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, empresaDBTypes, true, empresaPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize Empresa struct: %s", err)
	}

	if rowsAff, err := o.Update(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("should only affect one row but affected", rowsAff)
	}
}

func testEmpresasSliceUpdateAll(t *testing.T) {
	t.Parallel()

	if len(empresaAllColumns) == len(empresaPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &Empresa{}
	if err = randomize.Struct(seed, o, empresaDBTypes, true, empresaColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Empresa struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := Empresas().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, empresaDBTypes, true, empresaPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize Empresa struct: %s", err)
	}

	// Remove Primary keys and unique columns from what we plan to update
	var fields []string
	if strmangle.StringSliceMatch(empresaAllColumns, empresaPrimaryKeyColumns) {
		fields = empresaAllColumns
	} else {
		fields = strmangle.SetComplement(
			empresaAllColumns,
			empresaPrimaryKeyColumns,
		)
	}

	value := reflect.Indirect(reflect.ValueOf(o))
	typ := reflect.TypeOf(o).Elem()
	n := typ.NumField()

	updateMap := M{}
	for _, col := range fields {
		for i := 0; i < n; i++ {
			f := typ.Field(i)
			if f.Tag.Get("boil") == col {
				updateMap[col] = value.Field(i).Interface()
			}
		}
	}

	slice := EmpresaSlice{o}
	if rowsAff, err := slice.UpdateAll(ctx, tx, updateMap); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("wanted one record updated but got", rowsAff)
	}
}

